import { useState } from "react";
import { Link } from "react-router-dom";
import SummeryApi from "../common";


const SignIn = () => {
  const [formData, setFormData] = useState({});
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.id]: e.target.value });
  };


  const handleSubmit = async (e) => {
    e.preventDefault();

    try{
      setLoading(true)
      setError(false);
      console.log("Submitting to API:", SummeryApi.signin.url);
      
      const res = await fetch(SummeryApi.signin.url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData), 
      });
      const data=await res.json();

     setLoading(false);

     if(data.success===false){
      setError(true);
      return;

     }

    }catch(err){
      setError(true);
      setLoading(false);
    } 
  
  };

  
  
  return (
    <div className="p-3 max-w-lg mx-auto">
      <h1 className="text-3xl text-center font-semibold my-6">Sign In</h1>

      <form onSubmit={handleSubmit} className="flex flex-col gap-4">

        <input
          type="email"
          placeholder="email"
          id="email"
          className="bg-slate-100 p-3 rounded-lg"
          onChange={handleChange}
        />

        <input
          type="password"
          placeholder="password"
          id="password"
          className="bg-slate-100 p-3 rounded-lg"
          onChange={handleChange}
        />
        <button disabled={loading} className="p-3 bg-slate-700 rounded-lg text-white hover:opacity-95 disabled:opacity-80">
          {loading?'Loading...':'Sign In'}
        </button> 
        </form> 
        <div className="flex gap-2 mt-5">
          <p>DonHave an account?</p>
          <Link to="/sign-in">
            <span className="text-blue-500 hover:underline">Sign In</span>
          </Link>
        </div>
        <div>
          <p className='text-red-700 mt-5 font-bold'>{error && "something went wrong! "}</p>
        </div>
     
    </div>
  );
};

export default SignIn;
